insert into public.programs (id, code, name, short_name, description, accent, glyph) values
  ('ecele', 'ECELE', 'Electronics Engineering Licensure Examination', 'Electronics Engineering', 'The PRC board exam for Electronics Engineers. Master circuits, devices, electromagnetics and communications.', 'indigo', '📡'),
  ('ectle', 'ECTLE', 'Electronics Engineering Technician Licensure Examination', 'Electronics Engineering Technician', 'The PRC board exam for Electronics Engineering Technicians. Build hands-on mastery of devices, digital systems, troubleshooting and safety.', 'cyan', '🔧')
insert into public.subjects (id, program_id, name, code, description, glyph) values
  ('ecele-elecs', 'ecele', 'Electronics Engineering', 'ELECS', 'DC/AC circuits, devices, logic design, microcontrollers and control systems.', '⚡'),
  ('ecele-est', 'ecele', 'Electronic Systems & Design / Signals and Communications', 'EST', 'Signals, communications, transmission, data networks and CAD.', '📶'),
  ('ecele-math', 'ecele', 'Mathematics', 'MATH', 'Calculus, differential equations, advanced engineering math and data analysis.', '∑'),
  ('ecele-geas', 'ecele', 'General Engineering & Applied Sciences', 'GEAS', 'Chemistry, physics, economics, management, laws, ethics, safety and CAD.', '📊'),
  ('ectle-basics', 'ectle', 'Basic Electronics', 'BASICS', 'Components, symbols, diodes and transistors.', '🧰'),
  ('ectle-digital', 'ectle', 'Digital Electronics', 'DIGITAL', 'Logic gates, Boolean algebra and number systems.', '🔢'),
  ('ectle-electrical', 'ectle', 'Electrical Circuits & Measurements', 'ELEC', 'DC/AC circuits, meters and electrical power.', '🔋'),
  ('ectle-comm', 'ectle', 'Communications Systems', 'COMM', 'Radio, modulation and basic data networks.', '📻'),
  ('ectle-industrial', 'ectle', 'Industrial Electronics', 'INDUSTRIAL', 'Motors, relays, PLCs, safety and troubleshooting.', '🏭'),
  ('ectle-practical', 'ectle', 'Practical Applications', 'PRACTICAL', 'Soldering, assembly and test instruments.', '🛠️')
insert into public.topics (id, subject_id, program_id, name, description) values
  ('ecele-elecs-dc', 'ecele-elecs', 'ecele', 'DC Electrical Circuits', 'Ohm’s law, resistors and network theorems'),
  ('ecele-elecs-ac', 'ecele-elecs', 'ecele', 'AC Electrical Circuits', 'Phasors, RMS, resonance and AC power'),
  ('ecele-elecs-emag', 'ecele-elecs', 'ecele', 'Electromagnetics', 'Fields, waves and Maxwell’s equations'),
  ('ecele-elecs-devices', 'ecele-elecs', 'ecele', 'Electronic Devices and Circuits', 'Diodes, BJTs, FETs and amplifier basics'),
  ('ecele-elecs-circuit-design', 'ecele-elecs', 'ecele', 'Electronic Circuit Analysis and Design', 'Op-amps, Thevenin/Norton and filter design'),
  ('ecele-elecs-systems', 'ecele-elecs', 'ecele', 'Electronic Systems and Design', 'Rectifiers, power supplies and system integration'),
  ('ecele-elecs-logic', 'ecele-elecs', 'ecele', 'Logic Circuits and Switching Theory', 'Gates, Boolean algebra and combinational logic'),
  ('ecele-elecs-micro', 'ecele-elecs', 'ecele', 'Microprocessor & Microcontroller Systems and Design', 'Architectures, interrupts and interfacing'),
  ('ecele-elecs-control', 'ecele-elecs', 'ecele', 'Feedback and Control Systems', 'Closed-loop transfer functions and stability'),
  ('ecele-est-signals', 'ecele-est', 'ecele', 'Signals, Spectra, and Signal Processing', 'Fourier analysis, sampling and convolution'),
  ('ecele-est-principles', 'ecele-est', 'ecele', 'Principles of Communications', 'Modulation, demodulation and noise'),
  ('ecele-est-digital-comm', 'ecele-est', 'ecele', 'Digital Communications', 'Coding, error rates and digital modulation'),
  ('ecele-est-transmission', 'ecele-est', 'ecele', 'Transmission and Antenna Systems', 'Lines, impedance matching and antennas'),
  ('ecele-est-systems', 'ecele-est', 'ecele', 'Electronic Systems and Design', 'Amplifiers, filters and decibel gain'),
  ('ecele-est-data', 'ecele-est', 'ecele', 'Data Communications', 'Networking fundamentals, protocols and addressing'),
  ('ecele-est-cad', 'ecele-est', 'ecele', 'CAD', 'Computer-aided circuit design and PCB tools'),
  ('ecele-math-diff', 'ecele-math', 'ecele', 'Differential Calculus', 'Derivatives, rules and applications'),
  ('ecele-math-int', 'ecele-math', 'ecele', 'Integral Calculus', 'Antiderivatives and definite integrals'),
  ('ecele-math-de', 'ecele-math', 'ecele', 'Differential Equation', 'First and higher order ODEs'),
  ('ecele-math-advanced', 'ecele-math', 'ecele', 'Advanced Engineering Mathematics for ECE', 'Laplace transforms, complex variables and series'),
  ('ecele-math-data', 'ecele-math', 'ecele', 'Engineering Data Analysis', 'Statistics, probability and distributions'),
  ('ecele-math-emag', 'ecele-math', 'ecele', 'Electromagnetics', 'Vector calculus applied to fields and potentials'),
  ('ecele-math-signals', 'ecele-math', 'ecele', 'Signals, Spectra, and Signal Processing', 'Transforms and spectral analysis for engineers'),
  ('ecele-math-control', 'ecele-math', 'ecele', 'Feedback and Control Systems', 'Stability criteria, root locus and poles'),
  ('ecele-geas-chem', 'ecele-geas', 'ecele', 'Chemistry for Engineers', 'Atomic structure, bonding, pH and stoichiometry'),
  ('ecele-geas-physics', 'ecele-geas', 'ecele', 'Physics for Engineers', 'Mechanics, energy and motion'),
  ('ecele-geas-econ', 'ecele-geas', 'ecele', 'Engineering Economics', 'Interest, annuities and cash flow'),
  ('ecele-geas-management', 'ecele-geas', 'ecele', 'Engineering Management', 'Project scheduling, PERT and Gantt charts'),
  ('ecele-geas-techno', 'ecele-geas', 'ecele', 'Technopreneurship 101', 'Business models, value proposition and funding'),
  ('ecele-geas-physics2', 'ecele-geas', 'ecele', 'Physics 2', 'Electrostatics, fields and magnetism'),
  ('ecele-geas-materials', 'ecele-geas', 'ecele', 'Materials Science and Engineering', 'Alloys, crystal structure and material properties'),
  ('ecele-geas-programming', 'ecele-geas', 'ecele', 'Computer Programming', 'Variables, control flow and algorithms'),
  ('ecele-geas-environment', 'ecele-geas', 'ecele', 'Environmental Science and Engineering', 'Pollution, waste management and sustainability'),
  ('ecele-geas-law', 'ecele-geas', 'ecele', 'ECE Laws, Contracts, Ethics, Standards & Safety', 'PRC laws, codes of ethics and workplace safety'),
  ('ecele-geas-cad', 'ecele-geas', 'ecele', 'CAD', 'Drafting standards, schematics and manufacturing files'),
  ('ectle-basics-components', 'ectle-basics', 'ectle', 'Components & Symbols', 'Resistors, capacitors and inductors'),
  ('ectle-basics-semi', 'ectle-basics', 'ectle', 'Diodes & Transistors', 'PN junction, Zener and BJT operation'),
  ('ectle-dig-logic', 'ectle-digital', 'ectle', 'Logic Gates & Boolean Algebra', 'AND, OR, NOT and De Morgan’s theorem'),
  ('ectle-dig-systems', 'ectle-digital', 'ectle', 'Number Systems & Memory', 'Binary, hex and basic memory devices'),
  ('ectle-elec-dc', 'ectle-electrical', 'ectle', 'DC Circuits & Measurements', 'Series/parallel circuits and meters'),
  ('ectle-elec-ac', 'ectle-electrical', 'ectle', 'AC Circuits & Power', 'Mains power, RMS and power factor'),
  ('ectle-comm-radio', 'ectle-comm', 'ectle', 'Radio & Modulation', 'Carrier, AM/FM and antenna basics'),
  ('ectle-comm-data', 'ectle-comm', 'ectle', 'Data & Networks', 'Cabling, connectors and OSI layers'),
  ('ectle-ind-control', 'ectle-industrial', 'ectle', 'Control Systems & Motors', 'Relays, contactors, motors and PLCs'),
  ('ectle-ind-safety', 'ectle-industrial', 'ectle', 'Safety & Troubleshooting', 'Grounding, fuses and fault finding'),
  ('ectle-prac-soldering', 'ectle-practical', 'ectle', 'Soldering & Assembly', 'Solder joints, tools and component orientation'),
  ('ectle-prac-instruments', 'ectle-practical', 'ectle', 'Test Instruments', 'Multimeters, scopes and signal generators')
insert into public.questions (id, program_id, subject_id, topic_id, prompt, options, answer_index, explanation, difficulty) values
  ('ecele-elecs-dc-q1', 'ecele', 'ecele-elecs', 'ecele-elecs-dc', 'A 12 V source is connected to a 4 Ω resistor. What is the current?', '["2 A","3 A","4 A","48 A"]'::jsonb, 1, 'By Ohm’s law, I = V / R = 12 / 4 = 3 A.', 'easy'),
  ('ecele-elecs-dc-q2', 'ecele', 'ecele-elecs', 'ecele-elecs-dc', 'Two resistors of 4 Ω and 6 Ω connected in series have an equivalent resistance of:', '["2.4 Ω","10 Ω","5 Ω","24 Ω"]'::jsonb, 1, 'Series resistances add directly: 4 + 6 = 10 Ω.', 'easy'),
  ('ecele-elecs-dc-q3', 'ecele', 'ecele-elecs', 'ecele-elecs-dc', 'The power dissipated by a 2 Ω resistor carrying 3 A is:', '["6 W","12 W","18 W","36 W"]'::jsonb, 2, 'P = I²R = 3² × 2 = 18 W.', 'medium'),
  ('ecele-elecs-ac-q1', 'ecele', 'ecele-elecs', 'ecele-elecs-ac', 'For a sinusoid with peak voltage Vp, the RMS voltage is:', '["Vp / 2","Vp / √2","Vp × √2","Vp"]'::jsonb, 1, 'Vrms = Vp / √2 ≈ 0.707 Vp for a sine wave.', 'easy'),
  ('ecele-elecs-ac-q2', 'ecele', 'ecele-elecs', 'ecele-elecs-ac', 'In a purely capacitive AC circuit, the current:', '["leads voltage by 90°","lags voltage by 90°","is in phase with voltage","leads by 180°"]'::jsonb, 0, 'For a capacitor, current leads voltage by 90° (ICE).', 'medium'),
  ('ecele-elecs-ac-q3', 'ecele', 'ecele-elecs', 'ecele-elecs-ac', 'Series resonance in an RLC circuit occurs when:', '["XL > XC","XL < XC","XL = XC","R = 0"]'::jsonb, 2, 'At resonance the inductive and capacitive reactances cancel: XL = XC.', 'medium'),
  ('ecele-elecs-emag-q1', 'ecele', 'ecele-elecs', 'ecele-elecs-emag', 'What is the approximate speed of an electromagnetic wave in free space?', '["3 × 10⁶ m/s","3 × 10⁸ m/s","3 × 10¹⁰ m/s","1.5 × 10⁸ m/s"]'::jsonb, 1, 'The speed of light in vacuum is approximately 3 × 10⁸ m/s.', 'easy'),
  ('ecele-elecs-emag-q2', 'ecele', 'ecele-elecs', 'ecele-elecs-emag', 'A wave has a frequency of 100 MHz. What is its wavelength in free space?', '["0.3 m","3 m","30 m","300 m"]'::jsonb, 1, 'λ = c / f = (3 × 10⁸) / (1 × 10⁸) = 3 m.', 'medium'),
  ('ecele-elecs-emag-q3', 'ecele', 'ecele-elecs', 'ecele-elecs-emag', 'The SI unit of magnetic flux density (B) is the:', '["Weber","Tesla","Henry","Gauss"]'::jsonb, 1, 'Magnetic flux density is measured in tesla (T); weber is the unit of flux.', 'easy'),
  ('ecele-elecs-devices-q1', 'ecele', 'ecele-elecs', 'ecele-elecs-devices', 'What is the approximate forward voltage drop of a silicon diode?', '["0.2 V","0.3 V","0.7 V","1.4 V"]'::jsonb, 2, 'A forward-biased silicon diode typically drops about 0.7 V; germanium drops about 0.3 V.', 'easy'),
  ('ecele-elecs-devices-q2', 'ecele', 'ecele-elecs', 'ecele-elecs-devices', 'In a common-emitter BJT amplifier, what is the phase relationship between input and output?', '["0°","90°","180°","270°"]'::jsonb, 2, 'A common-emitter stage inverts the signal, producing a 180° phase shift.', 'medium'),
  ('ecele-elecs-devices-q3', 'ecele', 'ecele-elecs', 'ecele-elecs-devices', 'The current gain β of a BJT is defined as:', '["Ic / Ib","Ib / Ic","Ie / Ib","Ic / Ie"]'::jsonb, 0, 'β (hFE) is the ratio of collector current to base current.', 'medium'),
  ('ecele-elecs-circuit-design-q1', 'ecele', 'ecele-elecs', 'ecele-elecs-circuit-design', 'An inverting op-amp has Rin = 2 kΩ and Rf = 10 kΩ. What is its closed-loop gain?', '["−2","−5","+5","+12"]'::jsonb, 1, 'For an ideal inverting amplifier, gain = −Rf/Rin = −10/2 = −5.', 'medium'),
  ('ecele-elecs-circuit-design-q2', 'ecele', 'ecele-elecs', 'ecele-elecs-circuit-design', 'The Thevenin equivalent of a linear network consists of:', '["a current source in parallel with a resistor","a voltage source in series with a resistor","a voltage source in parallel with a capacitor","a resistor only"]'::jsonb, 1, 'Thevenin’s theorem reduces a network to Vth in series with Rth.', 'easy'),
  ('ecele-elecs-systems-q1', 'ecele', 'ecele-elecs', 'ecele-elecs-systems', 'How many diodes are used in a full-wave bridge rectifier?', '["2","4","6","8"]'::jsonb, 1, 'A bridge rectifier uses four diodes arranged in a diamond configuration.', 'easy'),
  ('ecele-elecs-systems-q2', 'ecele', 'ecele-elecs', 'ecele-elecs-systems', 'The main purpose of a filter in a DC power supply is to:', '["increase ripple","reduce ripple","raise the frequency","invert the polarity"]'::jsonb, 1, 'Filtering smooths the rectified waveform by reducing residual AC ripple.', 'easy'),
  ('ecele-elecs-logic-q1', 'ecele', 'ecele-elecs', 'ecele-elecs-logic', 'A NAND gate output is LOW only when:', '["all inputs are LOW","any input is HIGH","all inputs are HIGH","inputs are equal"]'::jsonb, 2, 'NAND is the inverse of AND: it is LOW only when every input is HIGH.', 'easy'),
  ('ecele-elecs-logic-q2', 'ecele', 'ecele-elecs', 'ecele-elecs-logic', 'Using Boolean algebra, A + Ā equals:', '["0","1","A","Ā"]'::jsonb, 1, 'The complement law states that a variable ORed with its complement always equals 1.', 'easy'),
  ('ecele-elecs-logic-q3', 'ecele', 'ecele-elecs', 'ecele-elecs-logic', 'How many distinct values can a 4-bit binary word represent?', '["8","15","16","32"]'::jsonb, 2, 'An n-bit word represents 2ⁿ values, so 2⁴ = 16 (0 through 15).', 'easy'),
  ('ecele-elecs-micro-q1', 'ecele', 'ecele-elecs', 'ecele-elecs-micro', 'A microcontroller integrates which of the following on a single chip?', '["CPU, memory and peripherals","only a CPU","only memory","only an oscillator"]'::jsonb, 0, 'A microcontroller combines processor, memory and I/O peripherals in one package.', 'easy'),
  ('ecele-elecs-micro-q2', 'ecele', 'ecele-elecs', 'ecele-elecs-micro', 'An interrupt causes the processor to:', '["halt permanently","temporarily suspend the current task to service an event","increase its clock speed","reset all memory"]'::jsonb, 1, 'Interrupts redirect execution to a service routine, then return to the interrupted task.', 'medium'),
  ('ecele-elecs-control-q1', 'ecele', 'ecele-elecs', 'ecele-elecs-control', 'Compared with an open-loop system, negative feedback generally:', '["increases gain and reduces stability","reduces gain and improves stability","has no effect on gain","eliminates the need for gain"]'::jsonb, 1, 'Negative feedback trades gain for improved stability, bandwidth and accuracy.', 'medium'),
  ('ecele-elecs-control-q2', 'ecele', 'ecele-elecs', 'ecele-elecs-control', 'For a forward path G(s) and feedback H(s), the closed-loop transfer function with negative feedback is:', '["G / (1 + GH)","G / (1 − GH)","GH / (1 + G)","1 + GH"]'::jsonb, 0, 'The standard negative-feedback closed-loop form is T(s) = G(s) / (1 + G(s)H(s)).', 'hard'),
  ('ecele-est-signals-q1', 'ecele', 'ecele-est', 'ecele-est-signals', 'The Fourier transform of a time-domain signal gives its:', '["phase spectrum only","frequency spectrum","time derivative","DC value only"]'::jsonb, 1, 'The Fourier transform maps a signal from the time domain to the frequency domain.', 'easy'),
  ('ecele-est-signals-q2', 'ecele', 'ecele-est', 'ecele-est-signals', 'According to the Nyquist sampling theorem, the sampling frequency must be:', '["equal to fm","at least 2fm","at most 2fm","half of fm"]'::jsonb, 1, 'To avoid aliasing, fs must be at least twice the highest message frequency.', 'easy'),
  ('ecele-est-principles-q1', 'ecele', 'ecele-est', 'ecele-est-principles', 'For an AM wave, the modulation index m is given by:', '["(Emax − Emin) / (Emax + Emin)","(Emax + Emin) / (Emax − Emin)","Emax / Emin","Emin / Emax"]'::jsonb, 0, 'The modulation index is computed from the envelope maxima and minima.', 'medium'),
  ('ecele-est-principles-q2', 'ecele', 'ecele-est', 'ecele-est-principles', 'Which modulation scheme keeps the carrier amplitude constant?', '["AM","FM","ASK","PAM"]'::jsonb, 1, 'Frequency modulation varies frequency while the amplitude remains constant.', 'easy'),
  ('ecele-est-digital-comm-q1', 'ecele', 'ecele-est', 'ecele-est-digital-comm', 'The theoretical minimum bandwidth for binary baseband signalling at bit rate Rb is:', '["Rb","Rb/2","2Rb","4Rb"]'::jsonb, 1, 'Nyquist’s criterion gives a minimum bandwidth of Rb/2 Hz for ideal binary signalling.', 'hard'),
  ('ecele-est-digital-comm-q2', 'ecele', 'ecele-est', 'ecele-est-digital-comm', 'A bit error rate of 10⁻⁶ means:', '["1 error per 10 bits","1 error per 1,000 bits","1 error per 1,000,000 bits","1 error per 100 bits"]'::jsonb, 2, 'BER is the ratio of erroneous bits to total transmitted bits, so 10⁻⁶ = 1 in a million.', 'medium'),
  ('ecele-est-transmission-q1', 'ecele', 'ecele-est', 'ecele-est-transmission', 'For a lossless transmission line, the characteristic impedance is:', '["Zo = √(L/C)","Zo = √(C/L)","Zo = L/C","Zo = LC"]'::jsonb, 0, 'The lossless line impedance is Zo = √(L/C), purely real.', 'medium'),
  ('ecele-est-transmission-q2', 'ecele', 'ecele-est', 'ecele-est-transmission', 'A VSWR of exactly 1 indicates:', '["a complete mismatch","a perfect match","a short circuit","an open circuit"]'::jsonb, 1, 'VSWR = 1 means no reflected wave — the load is perfectly matched to the line.', 'easy'),
  ('ecele-est-systems-q1', 'ecele', 'ecele-est', 'ecele-est-systems', 'A filter that passes all frequencies below a cutoff frequency is a:', '["high-pass filter","low-pass filter","band-stop filter","notch filter"]'::jsonb, 1, 'A low-pass filter passes frequencies from DC up to its cutoff frequency.', 'easy'),
  ('ecele-est-systems-q2', 'ecele', 'ecele-est', 'ecele-est-systems', 'The bandwidth of an amplifier is defined as:', '["the upper cutoff frequency only","the difference between upper and lower cutoff frequencies","the gain at DC","the sum of cutoff frequencies"]'::jsonb, 1, 'Bandwidth = fH − fL for a band-limited amplifier.', 'medium'),
  ('ecele-est-data-q1', 'ecele', 'ecele-est', 'ecele-est-data', 'An IPv4 address consists of:', '["16 bits","32 bits","64 bits","128 bits"]'::jsonb, 1, 'IPv4 uses 32-bit addresses, usually written in dotted-decimal notation.', 'easy'),
  ('ecele-est-data-q2', 'ecele', 'ecele-est', 'ecele-est-data', 'The connector most commonly used for twisted-pair Ethernet is:', '["RJ11","RJ45","BNC","USB-C"]'::jsonb, 1, 'Ethernet over twisted pair uses an 8-position RJ45 connector.', 'easy'),
  ('ecele-est-cad-q1', 'ecele', 'ecele-est', 'ecele-est-cad', 'CAD stands for:', '["Computer-Aided Design","Circuit Analysis and Design","Computer-Assisted Diagnostics","Centralized Array Data"]'::jsonb, 0, 'CAD is the use of computer systems to aid in design and drafting.', 'easy'),
  ('ecele-est-cad-q2', 'ecele', 'ecele-est', 'ecele-est-cad', 'Which file format is standard for PCB fabrication artwork?', '["PDF","Gerber","JPEG","MP3"]'::jsonb, 1, 'Gerber files describe the copper layers, solder mask and silkscreen for PCB manufacturing.', 'medium'),
  ('ecele-math-diff-q1', 'ecele', 'ecele-math', 'ecele-math-diff', 'What is the derivative of f(x) = x³ + 2x?', '["3x² + 2","3x² + 2x","x² + 2","3x + 2"]'::jsonb, 0, 'Apply the power rule: d/dx(x³) = 3x² and d/dx(2x) = 2.', 'easy'),
  ('ecele-math-diff-q2', 'ecele', 'ecele-math', 'ecele-math-diff', 'The derivative of sin x with respect to x is:', '["−sin x","cos x","−cos x","tan x"]'::jsonb, 1, 'The basic trigonometric derivative is d(sin x)/dx = cos x.', 'easy'),
  ('ecele-math-int-q1', 'ecele', 'ecele-math', 'ecele-math-int', 'Evaluate ∫ 2x dx.', '["x² + C","2 + C","x + C","2x² + C"]'::jsonb, 0, 'The antiderivative of 2x is x²; always add the constant of integration C.', 'easy'),
  ('ecele-math-int-q2', 'ecele', 'ecele-math', 'ecele-math-int', 'A definite integral of a positive function over [a, b] gives the:', '["slope at b","area under the curve","average value only","length of the curve"]'::jsonb, 1, 'The definite integral equals the signed area between the curve and the x-axis.', 'easy'),
  ('ecele-math-de-q1', 'ecele', 'ecele-math', 'ecele-math-de', 'The order of a differential equation is defined as:', '["the highest power of a derivative","the highest derivative present","the number of variables","the number of terms"]'::jsonb, 1, 'Order is determined by the highest-order derivative that appears.', 'easy'),
  ('ecele-math-de-q2', 'ecele', 'ecele-math', 'ecele-math-de', 'The general solution of dy/dx = ky is:', '["y = kx + C","y = Ce^{kx}","y = C/k","y = k ln x + C"]'::jsonb, 1, 'Separating variables and integrating gives ln|y| = kx + C, so y = Ce^{kx}.', 'medium'),
  ('ecele-math-advanced-q1', 'ecele', 'ecele-math', 'ecele-math-advanced', 'The Laplace transform of e^{at} is:', '["1/(s − a)","1/(s + a)","a/(s² + a²)","s/(s² − a²)"]'::jsonb, 0, 'L{e^{at}} = ∫₀∞ e^{−st}e^{at} dt = 1/(s − a) for s > a.', 'medium'),
  ('ecele-math-advanced-q2', 'ecele', 'ecele-math', 'ecele-math-advanced', 'The magnitude of a complex number a + bi is:', '["a² + b²","√(a² + b²)","a + b","√(a² − b²)"]'::jsonb, 1, 'Magnitude (modulus) is the distance from the origin in the complex plane.', 'easy'),
  ('ecele-math-data-q1', 'ecele', 'ecele-math', 'ecele-math-data', 'Find the mean of the data set {2, 4, 6, 8}.', '["4","5","6","7"]'::jsonb, 1, 'Mean = (2 + 4 + 6 + 8) / 4 = 20 / 4 = 5.', 'easy'),
  ('ecele-math-data-q2', 'ecele', 'ecele-math', 'ecele-math-data', 'For a normal distribution, approximately what percentage of values lie within ±1 standard deviation of the mean?', '["50%","68%","95%","99.7%"]'::jsonb, 1, 'The empirical rule gives about 68% within one sigma.', 'medium'),
  ('ecele-math-emag-q1', 'ecele', 'ecele-math', 'ecele-math-emag', 'Maxwell’s equations collectively describe the relationship between:', '["electric and magnetic fields","heat and work","stress and strain","pressure and volume"]'::jsonb, 0, 'Maxwell’s equations unify electricity and magnetism into electromagnetics.', 'easy'),
  ('ecele-math-emag-q2', 'ecele', 'ecele-math', 'ecele-math-emag', 'Electric flux density D is related to electric field intensity E by:', '["D = E / ε","D = εE","D = μH","D = E × H"]'::jsonb, 1, 'In a linear isotropic medium, D = εE.', 'medium'),
  ('ecele-math-signals-q1', 'ecele', 'ecele-math', 'ecele-math-signals', 'Convolution in the time domain corresponds to what operation in the frequency domain?', '["addition","multiplication","division","differentiation"]'::jsonb, 1, 'The convolution theorem states that time-domain convolution equals frequency-domain multiplication.', 'medium'),
  ('ecele-math-signals-q2', 'ecele', 'ecele-math', 'ecele-math-signals', 'The unit impulse δ(t) has an area (integral over all time) equal to:', '["0","1","∞","depends on amplitude"]'::jsonb, 1, 'By definition, ∫δ(t)dt = 1 over all time.', 'easy'),
  ('ecele-math-control-q1', 'ecele', 'ecele-math', 'ecele-math-control', 'For a stable continuous-time closed-loop system, all poles must lie in:', '["the right half-plane","the left half-plane","on the imaginary axis","at the origin"]'::jsonb, 1, 'Stability requires all closed-loop poles to have negative real parts.', 'medium'),
  ('ecele-math-control-q2', 'ecele', 'ecele-math', 'ecele-math-control', 'The Routh–Hurwitz criterion is used to determine:', '["frequency response bandwidth","stability from characteristic equation coefficients","signal-to-noise ratio","sampling rate"]'::jsonb, 1, 'Routh–Hurwitz tests stability without explicitly solving for roots.', 'hard'),
  ('ecele-geas-chem-q1', 'ecele', 'ecele-geas', 'ecele-geas-chem', 'The pH of a solution is defined as:', '["−log[H⁺]","log[H⁺]","[H⁺]²","1/[OH⁻]"]'::jsonb, 0, 'pH = −log₁₀ of the hydrogen ion concentration.', 'easy'),
  ('ecele-geas-chem-q2', 'ecele', 'ecele-geas', 'ecele-geas-chem', 'How many particles are in one mole of a substance?', '["6.022 × 10²³","3.14 × 10⁸","9.81 × 10²³","1.602 × 10⁻¹⁹"]'::jsonb, 0, 'Avogadro’s number is approximately 6.022 × 10²³ particles per mole.', 'easy'),
  ('ecele-geas-physics-q1', 'ecele', 'ecele-geas', 'ecele-geas-physics', 'Newton’s second law of motion states that:', '["F = m/a","F = ma","F = mv","F = m/a²"]'::jsonb, 1, 'Net force equals mass times acceleration.', 'easy'),
  ('ecele-geas-physics-q2', 'ecele', 'ecele-geas', 'ecele-geas-physics', 'The kinetic energy of a mass m moving at speed v is:', '["mv","½mv²","mgh","mv²"]'::jsonb, 1, 'KE = ½mv².', 'easy'),
  ('ecele-geas-econ-q1', 'ecele', 'ecele-geas', 'ecele-geas-econ', 'The simple interest on ₱1,000 at 10% per year for 2 years is:', '["₱100","₱200","₱220","₱1,200"]'::jsonb, 1, 'I = P × r × t = 1000 × 0.10 × 2 = ₱200.', 'easy'),
  ('ecele-geas-econ-q2', 'ecele', 'ecele-geas', 'ecele-geas-econ', 'An annuity is best described as:', '["a single lump-sum payment","a series of equal payments at equal intervals","a one-time investment","an irregular cash inflow"]'::jsonb, 1, 'An annuity is a sequence of equal payments made at regular time intervals.', 'easy'),
  ('ecele-geas-management-q1', 'ecele', 'ecele-geas', 'ecele-geas-management', 'In PERT, the expected activity time is computed as:', '["(O + M + P) / 3","(O + 4M + P) / 6","(O + 2M + P) / 4","(O + P) / 2"]'::jsonb, 1, 'PERT expected time = (optimistic + 4×most likely + pessimistic) / 6.', 'medium'),
  ('ecele-geas-management-q2', 'ecele', 'ecele-geas', 'ecele-geas-management', 'The critical path of a project is:', '["the shortest path through the network","the longest path and determines project duration","the path with the most resources","always the first activity"]'::jsonb, 1, 'The longest-duration path sets the minimum project completion time.', 'medium'),
  ('ecele-geas-techno-q1', 'ecele', 'ecele-geas', 'ecele-geas-techno', 'A business model canvas primarily describes:', '["how a company creates, delivers and captures value","only the financial statements","the circuit schematic","the org chart only"]'::jsonb, 0, 'The canvas maps key partners, activities, resources, value propositions, customers and revenue.', 'easy'),
  ('ecele-geas-techno-q2', 'ecele', 'ecele-geas', 'ecele-geas-techno', 'A value proposition explains:', '["why customers should choose your product","the company’s tax obligations","the manufacturing cost only","the legal structure"]'::jsonb, 0, 'It states the benefit that makes a product attractive to customers.', 'easy'),
  ('ecele-geas-physics2-q1', 'ecele', 'ecele-geas', 'ecele-geas-physics2', 'Coulomb’s law gives the force between charges as proportional to:', '["q₁q₂ / r","q₁q₂ / r²","q₁ + q₂ / r²","r² / q₁q₂"]'::jsonb, 1, 'F = k·q₁q₂ / r² — an inverse-square law.', 'easy'),
  ('ecele-geas-physics2-q2', 'ecele', 'ecele-geas', 'ecele-geas-physics2', 'Electric field intensity E at a point is defined as force per unit:', '["mass","charge","area","volume"]'::jsonb, 1, 'E = F / q (force per unit positive test charge).', 'easy'),
  ('ecele-geas-materials-q1', 'ecele', 'ecele-geas', 'ecele-geas-materials', 'Steel is primarily an alloy of iron and:', '["carbon","copper","aluminium","silver"]'::jsonb, 0, 'Steel is an iron-carbon alloy, often with additional alloying elements.', 'easy'),
  ('ecele-geas-materials-q2', 'ecele', 'ecele-geas', 'ecele-geas-materials', 'Compared with insulators, electrical conductors have:', '["higher resistivity","lower resistivity","the same resistivity","infinite resistivity"]'::jsonb, 1, 'Conductors allow easy charge flow because of their low resistivity.', 'easy'),
  ('ecele-geas-programming-q1', 'ecele', 'ecele-geas', 'ecele-geas-programming', 'A variable is best described as:', '["a named storage location for data","a type of loop","a compiler","a file extension"]'::jsonb, 0, 'Variables hold values that a program can read and modify.', 'easy'),
  ('ecele-geas-programming-q2', 'ecele', 'ecele-geas', 'ecele-geas-programming', 'A loop in a program is used to:', '["repeat a block of instructions","store a single value","define a function only","end the program"]'::jsonb, 0, 'Loops (for, while) repeat code until a condition changes.', 'easy'),
  ('ecele-geas-environment-q1', 'ecele', 'ecele-geas', 'ecele-geas-environment', 'Biochemical oxygen demand (BOD) is a measure of:', '["organic pollution in water","air temperature","soil pH only","noise level"]'::jsonb, 0, 'BOD indicates the amount of oxygen consumed by microorganisms decomposing organic matter.', 'medium'),
  ('ecele-geas-environment-q2', 'ecele', 'ecele-geas', 'ecele-geas-environment', 'The ozone layer primarily protects Earth’s surface from:', '["infrared radiation","ultraviolet radiation","radio waves","gamma rays"]'::jsonb, 1, 'Stratospheric ozone absorbs most harmful UV radiation.', 'easy'),
  ('ecele-geas-law-q1', 'ecele', 'ecele-geas', 'ecele-geas-law', 'The foremost obligation of an engineer under a code of ethics is to:', '["maximize profit","hold paramount the safety, health and welfare of the public","follow client instructions blindly","minimize project time"]'::jsonb, 1, 'Engineering codes of ethics place public safety, health and welfare above all else.', 'easy'),
  ('ecele-geas-law-q2', 'ecele', 'ecele-geas', 'ecele-geas-law', 'Before servicing electrical equipment, the safest first step is to:', '["remove only the fuse","disconnect and lock out/tag out the supply","wear thin gloves","increase the load"]'::jsonb, 1, 'De-energising and locking out the circuit prevents accidental re-energisation.', 'easy'),
  ('ecele-geas-cad-q1', 'ecele', 'ecele-geas', 'ecele-geas-cad', 'The difference between a schematic and a PCB layout is that a schematic:', '["shows logical connections, while layout defines physical placement and routing","shows only physical dimensions","is used only for documentation","cannot be simulated"]'::jsonb, 0, 'A schematic captures connectivity; the layout defines component positions and copper tracks.', 'medium'),
  ('ecele-geas-cad-q2', 'ecele', 'ecele-geas', 'ecele-geas-cad', 'DRC in a PCB design tool stands for:', '["Design Rule Check","Dynamic Resistance Calibration","Digital Route Control","Data Review Cycle"]'::jsonb, 0, 'DRC verifies that the design meets manufacturing and electrical rules.', 'easy'),
  ('ectle-basics-components-q1', 'ectle', 'ectle-basics', 'ectle-basics-components', 'A resistor with colour bands brown–black–red has a resistance of:', '["100 Ω","1 kΩ","10 kΩ","100 kΩ"]'::jsonb, 1, 'Brown = 1, black = 0, red = ×100, giving 10 × 100 = 1,000 Ω = 1 kΩ.', 'medium'),
  ('ectle-basics-components-q2', 'ectle', 'ectle-basics', 'ectle-basics-components', 'Which component stores energy in an electric field?', '["Resistor","Capacitor","Inductor","Diode"]'::jsonb, 1, 'A capacitor stores energy in the electric field between its plates.', 'easy'),
  ('ectle-basics-components-q3', 'ectle', 'ectle-basics', 'ectle-basics-components', 'Which component opposes changes in current flow?', '["Capacitor","Inductor","Resistor","LED"]'::jsonb, 1, 'An inductor resists changes in current by inducing a opposing voltage.', 'medium'),
  ('ectle-basics-semi-q1', 'ectle', 'ectle-basics', 'ectle-basics-semi', 'A PN junction diode conducts when it is:', '["forward biased","reverse biased","unbiased","at breakdown always"]'::jsonb, 0, 'Forward bias lowers the barrier potential and allows current to flow.', 'easy'),
  ('ectle-basics-semi-q2', 'ectle', 'ectle-basics', 'ectle-basics-semi', 'In an NPN transistor, the arrow on the emitter points:', '["toward the base","outward, away from the base","inward, toward the base","there is no arrow"]'::jsonb, 1, 'The NPN arrow points outward — “Not Pointing iN”.', 'medium'),
  ('ectle-basics-semi-q3', 'ectle', 'ectle-basics', 'ectle-basics-semi', 'A Zener diode is primarily used for:', '["amplification","voltage regulation","rectification only","light emission"]'::jsonb, 1, 'Zener diodes operate in reverse breakdown to maintain a reference voltage.', 'medium'),
  ('ectle-dig-logic-q1', 'ectle', 'ectle-digital', 'ectle-dig-logic', 'The output of an OR gate is HIGH when:', '["all inputs are LOW","at least one input is HIGH","inputs are different","all inputs are HIGH only"]'::jsonb, 1, 'An OR gate outputs HIGH if any input is HIGH.', 'easy'),
  ('ectle-dig-logic-q2', 'ectle', 'ectle-digital', 'ectle-dig-logic', 'An XOR gate outputs 1 when:', '["both inputs are 0","both inputs are 1","the inputs are different","either input is 1"]'::jsonb, 2, 'XOR (exclusive OR) is true only when the inputs differ.', 'easy'),
  ('ectle-dig-logic-q3', 'ectle', 'ectle-digital', 'ectle-dig-logic', 'De Morgan’s theorem states that (A·B)′ equals:', '["A′·B′","A′ + B′","A + B","A·B"]'::jsonb, 1, 'De Morgan: the complement of a product equals the sum of the complements.', 'medium'),
  ('ectle-dig-systems-q1', 'ectle', 'ectle-digital', 'ectle-dig-systems', 'The binary number 1010 is equal to the decimal value:', '["8","9","10","12"]'::jsonb, 2, '1010₂ = 8 + 0 + 2 + 0 = 10.', 'easy'),
  ('ectle-dig-systems-q2', 'ectle', 'ectle-digital', 'ectle-dig-systems', 'The hexadecimal digit F represents the decimal value:', '["10","14","15","16"]'::jsonb, 2, 'Hex digits run 0–9 then A=10 through F=15.', 'easy'),
  ('ectle-dig-systems-q3', 'ectle', 'ectle-digital', 'ectle-dig-systems', 'One byte consists of:', '["4 bits","8 bits","16 bits","32 bits"]'::jsonb, 1, 'A byte is 8 bits and can represent 256 distinct values.', 'easy'),
  ('ectle-elec-dc-q1', 'ectle', 'ectle-electrical', 'ectle-elec-dc', 'An ammeter must be connected:', '["in parallel with the load","in series with the load","across the supply only","to ground only"]'::jsonb, 1, 'An ammeter measures current and must be placed in series so the same current flows through it.', 'easy'),
  ('ectle-elec-dc-q2', 'ectle', 'ectle-electrical', 'ectle-elec-dc', 'A good voltmeter has:', '["very low internal resistance","very high internal resistance","zero internal resistance","no internal resistance"]'::jsonb, 1, 'High internal resistance minimises the current drawn from the circuit under test.', 'medium'),
  ('ectle-elec-dc-q3', 'ectle', 'ectle-electrical', 'ectle-elec-dc', 'The power dissipated in a resistor can be computed as:', '["P = V × I","P = I²R","P = V²/R","All of the above"]'::jsonb, 3, 'All three expressions are equivalent via Ohm’s law.', 'easy'),
  ('ectle-elec-ac-q1', 'ectle', 'ectle-electrical', 'ectle-elec-ac', 'The standard mains frequency in the Philippines is:', '["50 Hz","60 Hz","100 Hz","400 Hz"]'::jsonb, 1, 'Philippine mains power is nominally 220 V at 60 Hz.', 'easy'),
  ('ectle-elec-ac-q2', 'ectle', 'ectle-electrical', 'ectle-elec-ac', 'The RMS value of a 220 V AC mains rating refers to:', '["peak voltage","average voltage","effective voltage","peak-to-peak voltage"]'::jsonb, 2, 'AC voltage ratings are normally RMS (effective) values.', 'medium'),
  ('ectle-elec-ac-q3', 'ectle', 'ectle-electrical', 'ectle-elec-ac', 'Power factor is defined as:', '["the ratio of real to apparent power","the ratio of apparent to real power","the sine of the phase angle","the supply frequency"]'::jsonb, 0, 'PF = cos φ = real power / apparent power.', 'medium'),
  ('ectle-comm-radio-q1', 'ectle', 'ectle-comm', 'ectle-comm-radio', 'Modulation is the process of:', '["amplifying a carrier","varying a carrier with an information signal","filtering noise only","converting AC to DC"]'::jsonb, 1, 'Modulation impresses information onto a high-frequency carrier for transmission.', 'easy'),
  ('ectle-comm-radio-q2', 'ectle', 'ectle-comm', 'ectle-comm-radio', 'The standard AM broadcast band extends approximately from:', '["530 to 1700 kHz","88 to 108 MHz","3 to 30 MHz","1 to 2 GHz"]'::jsonb, 0, 'The AM broadcast band is roughly 530–1700 kHz (medium wave).', 'medium'),
  ('ectle-comm-radio-q3', 'ectle', 'ectle-comm', 'ectle-comm-radio', 'A quarter-wave antenna at 100 MHz is approximately:', '["0.075 m","0.75 m","3 m","7.5 m"]'::jsonb, 1, 'λ = 3 m at 100 MHz, so λ/4 = 0.75 m.', 'medium'),
  ('ectle-comm-data-q1', 'ectle', 'ectle-comm', 'ectle-comm-data', 'The connector most commonly used for twisted-pair Ethernet is:', '["RJ11","RJ45","BNC","USB-C"]'::jsonb, 1, 'Ethernet over twisted pair uses an 8-position RJ45 connector.', 'easy'),
  ('ectle-comm-data-q2', 'ectle', 'ectle-comm', 'ectle-comm-data', 'A network hub operates at which OSI layer?', '["Physical","Data Link","Network","Transport"]'::jsonb, 0, 'A hub simply repeats electrical signals and works at the physical layer.', 'medium'),
  ('ectle-comm-data-q3', 'ectle', 'ectle-comm', 'ectle-comm-data', 'Category 5e cable supports data rates up to:', '["10 Mbps","100 Mbps","1 Gbps","10 Gbps"]'::jsonb, 2, 'Cat5e is specified for Gigabit Ethernet (1000BASE-T) up to 100 m.', 'medium'),
  ('ectle-ind-control-q1', 'ectle', 'ectle-industrial', 'ectle-ind-control', 'A relay is best described as:', '["a solid-state amplifier","an electrically operated switch","a voltage regulator","a current source"]'::jsonb, 1, 'A relay uses an electromagnet to open or close contacts, isolating control from load.', 'easy'),
  ('ectle-ind-control-q2', 'ectle', 'ectle-industrial', 'ectle-ind-control', 'The synchronous speed of an induction motor depends on:', '["supply frequency and number of poles","load torque only","armature resistance","ambient temperature"]'::jsonb, 0, 'Ns = 120f / P, so speed depends on frequency and pole count.', 'medium'),
  ('ectle-ind-control-q3', 'ectle', 'ectle-industrial', 'ectle-ind-control', 'PLC stands for:', '["Programmable Logic Controller","Power Line Conduit","Personal Logic Circuit","Programmed Load Control"]'::jsonb, 0, 'A PLC is a ruggedised digital computer used for industrial automation.', 'easy'),
  ('ectle-ind-safety-q1', 'ectle', 'ectle-industrial', 'ectle-ind-safety', 'Before servicing electrical equipment, you should first:', '["remove the fuse only","disconnect and lock out the power supply","wear thin gloves","increase the load"]'::jsonb, 1, 'Lockout/tagout and de-energising the circuit is the essential first safety step.', 'easy'),
  ('ectle-ind-safety-q2', 'ectle', 'ectle-industrial', 'ectle-ind-safety', 'A fuse primarily protects a circuit against:', '["overvoltage","overcurrent","low frequency","reverse polarity"]'::jsonb, 1, 'A fuse opens the circuit when current exceeds its rated value.', 'easy'),
  ('ectle-ind-safety-q3', 'ectle', 'ectle-industrial', 'ectle-ind-safety', 'Equipping metal enclosures with a safety ground helps prevent:', '["electric shock","voltage sag","radio interference","power factor penalty"]'::jsonb, 0, 'Grounding provides a low-resistance fault path so protective devices trip quickly.', 'medium'),
  ('ectle-prac-soldering-q1', 'ectle', 'ectle-practical', 'ectle-prac-soldering', 'Traditional solder is an alloy mainly of:', '["copper and zinc","tin and lead","silver and gold","aluminium and iron"]'::jsonb, 1, 'Conventional solder is a tin-lead alloy; lead-free variants use tin with silver/copper.', 'easy'),
  ('ectle-prac-soldering-q2', 'ectle', 'ectle-practical', 'ectle-prac-soldering', 'Before use, the tip of a soldering iron should be:', '["painted","tinned","sandblasted","oiled"]'::jsonb, 1, 'Tinning the tip with solder improves heat transfer and prevents oxidation.', 'medium'),
  ('ectle-prac-soldering-q3', 'ectle', 'ectle-practical', 'ectle-prac-soldering', 'On an IC package, the notch or dot identifies:', '["pin 1","the last pin","ground only","the negative supply"]'::jsonb, 0, 'The notch/dot marks pin 1 and the pins are then counted counter-clockwise.', 'medium'),
  ('ectle-prac-instruments-q1', 'ectle', 'ectle-practical', 'ectle-prac-instruments', 'An oscilloscope primarily displays:', '["current versus temperature","voltage versus time","resistance versus frequency","power versus time"]'::jsonb, 1, 'An oscilloscope plots instantaneous voltage on the vertical axis against time horizontally.', 'easy'),
  ('ectle-prac-instruments-q2', 'ectle', 'ectle-practical', 'ectle-prac-instruments', 'A digital multimeter can typically measure:', '["voltage, current and resistance","only voltage","only current","frequency only"]'::jsonb, 0, 'The common DMM measures volts, amps and ohms, often with extra functions.', 'easy'),
  ('ectle-prac-instruments-q3', 'ectle', 'ectle-practical', 'ectle-prac-instruments', 'A function generator is used to produce:', '["DC power only","test waveforms such as sine and square","high-voltage transmission","mechanical rotation"]'::jsonb, 1, 'Function generators create repeatable test signals at adjustable frequency and amplitude.', 'easy')
